const makeLesson = (sections, practice, review) => ({
  learning: sections.map(
    ([title, objective, explanation, example, walkthrough, guidedPractice, takeaway], index) => ({
      title,
      duration: 5,
      objective,
      explanation:
        explanation +
        "\n\nArbeite den Gedanken bewusst nach: Benenne zuerst die Python-Regel, zeige im Beispiel die Stelle, an der sie greift, und sage das Ergebnis voraus, bevor du weiterliest. Prüfe auch, was sich ändern würde, wenn ein Wert oder eine Bedingung anders wäre.",
      example,
      walkthrough:
        walkthrough +
        "\n\nGehe jetzt selbst Zeile für Zeile vor: Notiere den Startzustand, verfolge jeden veränderten Wert und schreibe die sichtbare Ausgabe oder den Rückgabewert auf. Halte an jeder Entscheidung kurz inne und begründe, warum genau dieser Schritt als Nächstes ausgeführt wird.",
      practice:
        guidedPractice +
        "\n\nAktivaufgabe (ca. 5 Minuten): Tippe das Beispiel in eine lokale Python-Datei und führe es aus. Decke die Ausgabe zuerst ab und notiere deine Vorhersage. Ändere anschließend einen für diesen Abschnitt wichtigen Eingabewert oder Grenzfall, führe erneut aus und vergleiche beide Ergebnisse. Erkläre mit einem Satz, welche Regel den Unterschied verursacht.",
      takeaway,
    }),
  ),
  practice: [...practice.slice(0, -1), ...practiceExtensions[sections[0][0]], practice[practice.length - 1]].map((exercise) => ({
    ...exercise,
    duration: /^(Mini-Projekt|Abschlussprojekt)/.test(exercise.title) ? 8 : 4,
  })),
  review,
});

const choice = (title, prompt, options, answer, optionFeedback, explanation, hint, solution, duration = 4) => ({
  title, duration, prompt, type: "choice", options, answer, optionFeedback,
  explanation, errorFeedback: optionFeedback.filter((_, index) => index !== answer).join(" "),
  hint, solution, solutionLabel: "Lösung",
});

const written = (type, title, prompt, accepted, solution, explanation, errorFeedback, hint, duration = 5) => ({
  title, duration, prompt, type, accepted, solution, explanation, errorFeedback, hint,
  solutionLabel: "Beispiel-Lösung",
});

const project = (title, prompt, solution, explanation, errorFeedback, hint) => ({
  title, duration: 8, prompt, type: "self-check", solution, explanation, errorFeedback, hint,
  solutionLabel: "Ein möglicher Lösungsweg",
});

const reviewChoice = (prompt, options, answer, optionFeedback, explanation, hint, solution) => ({
  title: "Kurz wiederholen", duration: 2, prompt, type: "choice", options, answer, optionFeedback,
  explanation, hint, solution, solutionLabel: "Lösung",
});

const reviewReflection = (prompt, explanation, hint, solution) => ({
  title: "In eigenen Worten", duration: 2, prompt, type: "reflection", explanation,
  errorFeedback: "Nutze die Beispielantwort als Prüfliste: Benenne die Python-Regel und wende sie auf ein konkretes Beispiel an.",
  hint, solution, solutionLabel: "Beispielantwort",
});

const debugTask = (title, prompt, answer, explanation, errorFeedback, hint) => ({
  title, duration: 4, prompt, type: "code", accepted: [answer], solution: answer,
  explanation, errorFeedback, hint, solutionLabel: "Korrigierter Code",
});

const runAndTestTask = (title, prompt, solution, explanation, errorFeedback, hint) => ({
  title, duration: 4, prompt, type: "self-check", solution, explanation, errorFeedback, hint,
  solutionLabel: "Testbarer Lösungsweg",
});

